<?php

namespace App\Console\Commands;

use Illuminate\Console\Command;
use Maatwebsite\Excel\Facades\Excel;
use Maatwebsite\Excel\Concerns\FromArray;

class GenerateChatbotExcel extends Command
{
    protected $signature = 'chatbot:generate-excel';
    protected $description = 'Generate chatbot Q&A Excel file from PDF content';

    public function handle(): int
    {
        $data = $this->getData();

        $export = new class($data) implements FromArray {
            public function __construct(private array $rows) {}
            public function array(): array { return $this->rows; }
        };

        $stored = storage_path('app/public/chatbot-qa.xlsx');
        Excel::store($export, 'chatbot-qa.xlsx', 'public');

        $this->info('File saved to: ' . $stored);
        return 0;
    }

